import { Router } from "express";
import { authService } from "../services/auth-service";

export const loginRouter = Router();

// Login entry point for the demo: POST /api/login
loginRouter.post("/login", async (request, response) => {
  const { email, password } = request.body as {
    email?: string;
    password?: string;
  };

  if (!email || !password) {
    response.status(400).json({ error: "email and password are required" });
    return;
  }

  try {
    const result = await authService.login(email, password);
    response.status(200).json(result);
  } catch (error) {
    response.status(401).json({
      error: error instanceof Error ? error.message : "Login failed"
    });
  }
});
import { userRepository } from "../repositories/user-repository";
import { LoginResult } from "../types/user";
import { verifyPassword } from "../utils/password";
import { issueAccessToken } from "../utils/token";

export class AuthService {
  async login(email: string, password: string): Promise<LoginResult> {
    const user = await userRepository.findByEmail(email);

    if (!user) {
      throw new Error("User not found");
    }

    const passwordMatched = await verifyPassword(password, user.passwordHash);

    if (!passwordMatched) {
      throw new Error("Invalid password");
    }

    const accessToken = issueAccessToken({
      userId: user.id,
      role: user.role
    });

    return {
      accessToken,
      user: {
        id: user.id,
        email: user.email,
        displayName: user.displayName,
        role: user.role
      }
    };
  }
}

export const authService = new AuthService();
import { queryOne } from "../db/database";
import { UserRecord } from "../types/user";

export class UserRepository {
  async findByEmail(email: string): Promise<UserRecord | undefined> {
    // The repository is responsible for reading the users table.
    return queryOne("users", { email });
  }
}

export const userRepository = new UserRepository();
import { UserRecord } from "../types/user";

type TableName = "users";

const usersTable: UserRecord[] = [
  {
    id: "u_1001",
    email: "demo@example.com",
    passwordHash: "hash:demo123",
    displayName: "Demo User",
    role: "member"
  },
  {
    id: "u_1002",
    email: "admin@example.com",
    passwordHash: "hash:admin123",
    displayName: "Admin User",
    role: "admin"
  }
];

function getTable(table: TableName): UserRecord[] {
  if (table === "users") {
    return usersTable;
  }

  return [];
}

// Simulated database access so the repository can clearly show a users table lookup.
export async function queryOne(
  table: TableName,
  where: Partial<UserRecord>
): Promise<UserRecord | undefined> {
  const rows = getTable(table);

  return rows.find((row) =>
    Object.entries(where).every(([key, value]) => {
      const field = key as keyof UserRecord;
      return row[field] === value;
    })
  );
}
import { NextFunction, Request, Response } from "express";
import { parseAccessToken } from "../utils/token";

export function authMiddleware(
  request: Request,
  response: Response,
  next: NextFunction
): void {
  const authHeader = request.headers.authorization;

  if (!authHeader?.startsWith("Bearer ")) {
    response.status(401).json({ error: "Missing bearer token" });
    return;
  }

  const token = authHeader.replace("Bearer ", "");
  const payload = parseAccessToken(token);

  if (!payload) {
    response.status(401).json({ error: "Invalid token" });
    return;
  }

  response.locals.currentUser = payload;
  next();
}
// Demo-only password check: the stored hash is "hash:" + plain text password.
export async function verifyPassword(
  plainTextPassword: string,
  passwordHash: string
): Promise<boolean> {
  return passwordHash === `hash:${plainTextPassword}`;
}
import { AuthTokenPayload } from "../types/user";

export function issueAccessToken(payload: AuthTokenPayload): string {
  const encoded = Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
  return `demo-token.${encoded}`;
}

export function parseAccessToken(token: string): AuthTokenPayload | null {
  if (!token.startsWith("demo-token.")) {
    return null;
  }

  const encoded = token.replace("demo-token.", "");

  try {
    const json = Buffer.from(encoded, "base64url").toString("utf8");
    return JSON.parse(json) as AuthTokenPayload;
  } catch {
    return null;
  }
}

export interface UserRecord {
  id: string;
  email: string;
  passwordHash: string;
  displayName: string;
  role: "admin" | "member";
}

export interface LoginResult {
  accessToken: string;
  user: Pick<UserRecord, "id" | "email" | "displayName" | "role">;
}

export interface AuthTokenPayload {
  userId: string;
  role: UserRecord["role"];
}

